def best_xi(sq, k, s=BL):
    by={"GKP":[],"DEF":[],"MID":[],"FWD":[]}
    for i in sq: by[s[i]["pos"]].append((s[i]["ep_gw"][k], i))
    for p in by: by[p].sort(reverse=True)
    best=None
    gk=by["GKP"][0]
    for d,m,f in FORMS:
        if len(by["DEF"])<d or len(by["MID"])<m or len(by["FWD"])<f: continue
        xi=[gk]+by["DEF"][:d]+by["MID"][:m]+by["FWD"][:f]
        tot=sum(e for e,_ in xi)
        if best is None or tot>best[0]: best=(tot,[i for _,i in xi],(d,m,f))
    return best
def xi_ep6(sq, s=BL, cap=True):
    """Σ over GW5-10 of best-XI EP, plus captain (best XI EP) doubled each GW."""
    tot=0.0
    for k in range(6):
        t,xi,_=best_xi(sq,k,s)
        c=max(s[i]["ep_gw"][k] for i in xi) if cap else 0.0
        tot+=t+c
    return tot
def xi_ep6_nocap(sq, s=BL):
    return sum(best_xi(sq,k,s)[0] for k in range(6))
